//! Required Font size DOMString reflection retains actual attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><font id=para size=MiXeD></font><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://font-size.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn font_size_canonical_accessor_descriptor_and_initial_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),P=HTMLFontElement.prototype,a=Object.getOwnPropertyDescriptor(P,'size');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get size'||a.set.name!=='set size'||Object.hasOwn(x,'size')||x.size!=='MiXeD'||x.textContent!=='')throw 'canonical font size accessor';"#);}
#[test]
fn font_size_native_domstring_aliases_old_values_and_absent_default(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),attr=x.getAttributeNode('size'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.size='A\ud800Z';var records=watch.takeRecords();if(x.size!=='A\ud800Z'||attr.value!==x.size||x.getAttributeNode('size')!==attr||records.length!==1||records[0].attributeName!=='size'||records[0].oldValue!=='MiXeD'||x.textContent!=='')throw 'exact font size transaction';attr.nodeValue='unrestricted';if(x.size!=='unrestricted')throw 'ordinary string reflection';x.removeAttribute('size');if(x.size!==''||attr.ownerElement!==null||attr.value!=='unrestricted')throw 'removed size default';x.size=null;if(x.size!=='null'||document.getElementById('neighbor').value!=='seed')throw 'null DOMString conversion';"#);}
#[test]
fn font_size_inert_exact_namespace_once_conversion_and_independent_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:font');if(!(x instanceof HTMLFontElement)||x.size!=='')throw 'inert font size default';var calls=0;x.size={toString:function(){calls++;x.setAttribute('size','author');return 'R\udfffZ';}};if(calls!==1||x.size!=='R\udfffZ'||x.getAttribute('size')!==x.size)throw 'once exact conversion';x.setAttributeNS('urn:foreign','size','foreign');x.setAttributeNS(null,'ALIGN','upper');if(x.size!=='R\udfffZ')throw 'exact null namespace size';var clone=x.cloneNode(false);if(clone.size!==x.size)throw 'namespace copy';x.removeAttributeNS('urn:foreign','size');x.removeAttributeNS(null,'ALIGN');var copy=document.importNode(x,false);if(copy.size!==x.size||copy.ownerDocument!==document||clone.getAttributeNode('size')===x.getAttributeNode('size'))throw 'actual copies';clone.size='independent';if(x.size!=='R\udfffZ'||copy.size!=='R\udfffZ')throw 'independent copied size';"#);}

#[test]
fn font_size_conversion_reentry_abrupt_symbol_and_current_attr_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),old=x.getAttributeNode('size'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.size={toString:function(){calls++;x.removeAttribute('size');x.setAttribute('size','replacement');return 'A\ud800Z';}};var current=x.getAttributeNode('size'),records=watch.takeRecords();if(calls!==1||current===old||old.ownerElement!==null||old.value!=='MiXeD'||current.value!=='A\ud800Z'||records.length!==3||records[2].oldValue!=='replacement')throw 'current real Attr after conversion';var marker={},caught;try{x.size={toString:function(){x.setAttribute('size','author effect');throw marker;}};}catch(e){caught=e;}records=watch.takeRecords();if(caught!==marker||x.size!=='author effect'||records.length!==1||records[0].oldValue!=='A\ud800Z')throw 'abrupt conversion preserves author effect';caught=false;try{x.size=Symbol('div');}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.size!=='author effect')throw 'Symbol conversion refusal';for(var value of [null,undefined,0,false]){x.size=value;if(x.size!==String(value))throw 'ordinary DOMString conversion';}if(x.textContent!=='')throw 'metadata leaves displayed text';"#);
}

#[test]
fn font_size_descriptors_brands_author_override_and_saved_constructor(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),C=HTMLFontElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'size'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElement('hr'),document.createElement('menu'),document.createElement('dir'),document.createElement('p'),document.createElement('h1'),document.createElement('div'),document.createElement('legend'),document.getElementById('neighbor'),document.createElementNS('urn:foreign','font'),new Document().createElementNS('http://www.w3.org/1999/xhtml','FONT')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before conversion';}Object.defineProperty(x,'size',{value:'author',writable:true,configurable:true});if(x.size!=='author'||a.get.call(x)!=='MiXeD')throw 'canonical authority';a.set.call(x,'canonical');if(x.size!=='author'||x.getAttribute('size')!=='canonical')throw 'borrowed real setter';delete x.size;if(x.size!=='canonical'||Object.hasOwn(x,'size'))throw 'restored inherited reflection';delete window.HTMLFontElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved original interface';"#);
}

#[test]
fn font_size_native_inert_attribute_aliases_namespace_and_exact_copies(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','font');x.setAttribute('size','MiXeD');"}else{"var x=document.getElementById('para');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('size');for(var writer of ['value','nodeValue','textContent']){a[writer]='R\ud800'+writer;if(x.size!=='R\ud800'+writer||x.getAttributeNode('size')!==a)throw 'exact attached alias';}x.setAttributeNS('urn:foreign','size','foreign');x.setAttributeNS(null,'ALIGN','upper');if(x.size!=='R\ud800textContent'||x.getAttributeNodeNS(null,'size')!==a)throw 'exact null namespace/local name';x.setAttributeNS(null,'size','no date parsing');if(x.size!=='no date parsing'||a.value!==x.size)throw 'exact null namespace writer';var copy=x.cloneNode(false);if(copy.size!==x.size||copy.getAttributeNode('size')===a)throw 'independent clone';x.removeAttributeNS(null,'size');if(x.size!==''||a.ownerElement!==null||copy.size!=='no date parsing')throw 'removed actual default';"#);}
}

#[test]
fn font_size_native_adoption_and_return_keep_actual_interface_attr_and_child_handles(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),attr=x.getAttributeNode('size'),first=x.firstChild,list=x.childNodes,C=HTMLFontElement,doc=new Document();if(doc.adoptNode(x)!==x||x.ownerDocument!==doc||x.parentNode!==null||!(x instanceof C)||x.size!=='MiXeD'||attr.ownerElement!==x||attr.ownerDocument!==doc||x.firstChild!==first||x.childNodes!==list)throw 'actual native data adoption';x.size='A\udfffZ';if(document.adoptNode(x)!==x||x.ownerDocument!==document||x.size!=='A\udfffZ'||x.getAttributeNode('size')!==attr)throw 'same native identity return';document.body.appendChild(x);if(x.firstChild!==first||x.childNodes!==list||x.textContent!==''||attr.value!==x.size)throw 'reconnected data source';"#);
}

#[test]
fn font_size_saved_child_origin_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLFontElement,a=Object.getOwnPropertyDescriptor(C.prototype,'size'),calls=0;if(C===HTMLFontElement||a.get.call(x)!=='MiXeD')throw 'captured data accessor';"#);p.set_location(&crate::navigation::address("https://other-font-size.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://font-size.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered')throw 'data origin recovery';");
}

// Shared reflection transactions must refuse before observable changes.

#[test]
fn font_size_writer_refusal_preserves_native_and_inert_records_and_recovers(){
 for inert in [false,true]{for source in [r"x.size='Long canonical \ud800 Font size metadata replacement';",r"x.setAttribute('size','Long canonical \ud800 Font size metadata replacement');",r"attr.value='Long canonical \ud800 Font size metadata replacement';",r"attr.nodeValue='Long canonical \ud800 Font size metadata replacement';",r"attr.textContent='Long canonical \ud800 Font size metadata replacement';"]{for mode in 0..5{
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','font');x.setAttribute('size','MiXeD');"}else{"var x=document.getElementById('para');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('size'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("value writer {inert}/{source}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='MiXeD'||x.size!=='MiXeD'||watch.takeRecords().length)throw 'atomic value writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r"var records=watch.takeRecords();if(x.size!=='Long canonical \ud800 Font size metadata replacement'||records.length!==1||records[0].oldValue!=='MiXeD'||records[0].attributeName!=='size'||x.getAttributeNode('size')!==attr)throw 'fresh value writer recovery';");
 }}}
}

#[test]
fn font_size_reads_enforce_work_copy_string_and_deadline_without_retained_growth(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let object=if inert{run(&mut d,&mut f,&mut p,r"var data=new Document().createElementNS('http://www.w3.org/1999/xhtml','font');data.size='A\ud800Z';");let Value::Host(object)=p.runtime.execute("data;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert data handle")};object}else{run(&mut d,&mut f,&mut p,r"document.getElementById('para').size='A\ud800Z';");node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("para")).unwrap())};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.font_size_get(object);if mode==4{assert!(result.is_ok());}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time")||e.contains("bound"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.font_size_get(object).is_ok());}}
}

#[test]
fn font_size_clone_import_promotion_refusal_is_atomic_and_recovers(){
 for tag in ["font"]{for operation in ["clone","import","promote"]{for mode in 0..5{
  // Promotion reuses reserved main slots; its node limit is tested as a no-growth success below.
  if operation=="promote"&&mode==3{continue;}
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,source,watch=new MutationObserver(function(){{}});watch.observe(target,{{childList:true}});var which='{tag}';"));
  let source=match operation{
   "clone"=>{run(&mut d,&mut f,&mut p,"source=document.getElementById('para');");"var result=source.cloneNode(true);"},
   "import"=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.size='exact';");"var result=document.importNode(source,true);"},
   _=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.size='exact';");"var result=target.appendChild(source);"}
  };
  run(&mut d,&mut f,&mut p,"var oldParent=source.parentNode,oldFirst=source.firstChild,oldText=source.textContent,oldValue=source.getAttributeNode('size');");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let retained=p.state.retained;let commits=p.state.dom_commits;let attr_count=p.state.attributes.len();let detached=p.state.detached_nodes.clone();let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};
  let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("{tag}/{operation}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{tag}/{operation}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),(retained,commits,attr_count,detached));assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);
  p.state.retained_limit=limit;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.parentNode!==oldParent||source.firstChild!==oldFirst||source.textContent!==oldText||source.getAttributeNode('size')!==oldValue||watch.takeRecords().length)throw 'atomic gauge lifecycle refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,if operation=="promote"{"var records=watch.takeRecords();if(result!==source||source.parentNode!==target||source.firstChild!==oldFirst||source.getAttributeNode('size')!==oldValue||records.length!==1||records[0].addedNodes[0]!==source)throw 'promotion recovery';"}else{"if(result===source||result.parentNode!==null||result.size!==source.size||result.textContent!==source.textContent||source.parentNode!==oldParent||watch.takeRecords().length)throw 'copy recovery';"});
 }}}
}

