#[test]
fn font_size_real_text_descendants_copy_import_and_shallow_parking(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para');x.textContent='A\ud800Z';var first=x.firstChild,list=x.childNodes,attr=x.getAttributeNode('size');x.size='raw';if(x.textContent!=='A\ud800Z'||x.firstChild!==first||x.childNodes!==list)throw 'real text retained';var copy=x.cloneNode(true);if(copy.textContent!==x.textContent||copy.firstChild===first||copy.size!=='raw'||copy.getAttributeNode('size')===attr)throw 'independent real deep clone';copy.firstChild.nodeValue='changed';if(x.textContent!=='A\ud800Z')throw 'independent descendant';var doc=new Document(),imported=doc.importNode(x,true);if(imported.ownerDocument!==doc||imported.firstChild.ownerDocument!==doc||imported.textContent!==x.textContent||imported.size!=='raw')throw 'real inert import';var leaf=x.cloneNode(false),template=document.createElement('template');template.content.appendChild(leaf);document.body.appendChild(template);if(leaf.size!=='raw'||leaf.firstChild!==null||leaf.parentNode!==template.content||leaf.ownerDocument!==template.content.ownerDocument)throw 'shallow native template parking';"#);}

#[test]
fn font_size_independent_legacy_color_keeps_actual_handles(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var x of [document.getElementById('para'),new Document().createElementNS('http://www.w3.org/1999/xhtml','t:font')]){x.face='fixed';var face=x.getAttributeNode('face');x.color='stable';var color=x.getAttributeNode('color');x.size=null;if(x.size!=='null'||x.color!=='stable'||x.getAttributeNode('color')!==color)throw 'ordinary size null';x.color=null;if(x.color!==''||x.size!=='null')throw 'independent legacy color null';var attr=x.getAttributeNode('size'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.size={toString:function(){calls++;x.color='author';return 'A\ud800Z';}};var records=watch.takeRecords();if(x.face!=='fixed'||x.getAttributeNode('face')!==face||calls!==1||x.size!=='A\ud800Z'||x.color!=='author'||color.value!=='author'||x.getAttributeNode('size')!==attr||records.length!==2||records[0].attributeName!=='color'||records[1].attributeName!=='size'||records[1].oldValue!=='null')throw 'independent actual size conversion';x.removeAttribute('size');if(x.size!==''||attr.ownerElement!==null||x.color!=='author')throw 'independent size removal';}"#);}
